281	        let at = self.offset(); let n = self.read_u32()? as usize;
282	        // All vectors decoded by this helper have elements of at least one byte.
283	        if n > self.remaining() { return Err(Error::new(at, "vector length exceeds remaining input")); }
284	        let mut out = Vec::new();
