//! Instance state, ABI entry points, and module-wide LLVM definitions.
use std::collections::BTreeSet;
use std::fmt::Write;
use crate::{codegen, numeric, wasm};
use wasm::{ConstOp, DataMode, ExportDesc, ImportDesc, ElementMode, ElementInit, ValType};

fn hex(s:&str)->String {s.as_bytes().iter().map(|b|format!("{b:02x}")).collect()}
fn data_bytes(b:&[u8])->String {b.iter().map(|x|format!("\{x:02X}")).collect()}
fn expr(e:&wasm::ConstExpr)->Result<String,String> {Ok(match e.op {
    ConstOp::I32(x)=>(x as u32).to_string(),ConstOp::I64(x)=>(x as u64).to_string(),ConstOp::F32(x)=>x.to_string(),ConstOp::F64(x)=>x.to_string(),
    ConstOp::V128(x)=>u128::from_le_bytes(x).to_string(),ConstOp::RefNull(_)=>"0".into(),ConstOp::RefFunc(x)=>(x as u64+1).to_string(),
    ConstOp::GlobalGet(_)=>return Err("imported globals are not provided by the ABI".into()),
})}
fn offset(e:&wasm::ConstExpr)->Result<String,String> {match e.op { ConstOp::I32(n)=>Ok((n as u32).to_string()),_=>Err("non-i32 segment offset".into())}}

pub fn translate(m:&wasm::Module)->Result<String,String> {
    for i in &m.imports {if !matches!(i.desc,ImportDesc::Func(_)) {return Err("only function imports are supported by the host ABI".into())}}
    let memory=m.memory_type(0);
    let max=memory.map(|x|x.limits.max.unwrap_or(65536)).unwrap_or(65536);
    let mut out=String::from("target triple = "x86_64-unknown-linux-gnu"

");
    out.push_str(&include_str!("runtime.ll").replace("@W2L_MEMORY_MAX@",&max.to_string()));
    out.push_str(&numeric::declarations());
    let mut types=Vec::new();for t in &m.types {types.push(codegen::Sig{params:t.params.clone(),results:t.results.clone()});}
    let nf=m.imported_function_count()+m.functions.len();
    let mut funcs=Vec::new();for i in 0..nf {funcs.push(m.function_type_index(i as u32).ok_or("invalid function type")?);}
    let env=codegen::Env {types,funcs,globals:m.globals.iter().map(|g|(g.ty.ty,g.ty.mutable)).collect(),memory:memory.is_some(),tables:m.tables.iter().map(|t|t.element).collect(),data_count:m.data.len(),elem_count:m.elements.len()};
    for (i,_) in m.globals.iter().enumerate() {writeln!(out,"@w2l_g{i} = internal global i128 0, align 16").unwrap();}
    for (i,d) in m.data.iter().enumerate() {
        writeln!(out,"@w2l_data_{i} = private constant [{} x i8] c"{}"",d.bytes.len(),data_bytes(&d.bytes)).unwrap();
        writeln!(out,"@w2l_data_dropped_{i} = internal global i1 false").unwrap();
        writeln!(out,"define internal void @w2l_data_init_{i}(i32 %dst, i32 %src, i32 %n) {{
entry:
  %dropped = load i1, ptr @w2l_data_dropped_{i}
  %size = select i1 %dropped, i64 0, i64 {}
  %s = zext i32 %src to i64
  %len = zext i32 %n to i64
  %end = add i64 %s, %len
  %bad = icmp ugt i64 %end, %size
  br i1 %bad, label %trap, label %copy
trap:
  call void @w2l_trap(i32 4)
  unreachable
copy:
  %p = call ptr @w2l_mem_ptr(i32 %dst, i64 0, i64 %len)
  %q = getelementptr [{} x i8], ptr @w2l_data_{i}, i64 0, i64 %s
  call void @llvm.memcpy.p0.p0.i64(ptr %p, ptr %q, i64 %len, i1 false)
  ret void
}}",d.bytes.len(),d.bytes.len()).unwrap();
    }
    emit_tables(m,&mut out)?;
    let mut imported=0;
    let mut imported_symbols=BTreeSet::new();
    for i in &m.imports {if let ImportDesc::Func(_) = i.desc {
        let symbol=format!("w2l_import_{}_{}",hex(&i.module),hex(&i.name));
        if imported_symbols.insert(symbol.clone()){writeln!(out,"declare void @{symbol}(ptr, ptr)").unwrap();}
        writeln!(out,"define internal void @w2l_f{imported}(ptr %args, ptr %results) {{
entry:
  call void @{symbol}(ptr %args, ptr %results)
  ret void
}}").unwrap();imported+=1;
    }}
    let mut numeric_ops=BTreeSet::new();
    for (i,f) in m.functions.iter().enumerate() {
        let sig=env.types.get(f.type_index as usize).ok_or("invalid function type")?;
        let locals_count:f64=f.locals.iter().map(|l|l.count as f64).sum();
        if locals_count>1000000.0 {return Err("too many locals".into())}
        let locals:Vec<_>=f.local_types().collect();
        let ir=codegen::compile((imported+i) as u32,&env,sig,&locals,&f.body).map_err(|e|format!("function {}: {e}",imported+i))?;
        numeric_ops.extend(ir.numeric);out.push_str(&ir.body);
    }
    for op in numeric_ops {out.push_str(&numeric::helper(op)?);}
    emit_indirect(m,&mut out)?;
    out.push_str("define void @w2l_init() {
entry:
  store i32 0, ptr @w2l_depth
");
    if let Some(mem)=memory {let bytes=mem.limits.min as u64*65536;writeln!(out,"  %memory = call ptr @calloc(i64 {}, i64 1)
  %memory_oom = icmp eq ptr %memory, null
  br i1 %memory_oom, label %memory_failure, label %memory_ok
memory_failure:
  call void @w2l_trap(i32 4)
  unreachable
memory_ok:
  store ptr %memory, ptr @w2l_mem_base
  store i64 {bytes}, ptr @w2l_mem_bytes",bytes.max(1)).unwrap();}
    for (i,g) in m.globals.iter().enumerate() {writeln!(out,"  store i128 {}, ptr @w2l_g{i}, align 16",expr(&g.init)?).unwrap();}
    for (i,t) in m.tables.iter().enumerate() {let bytes=(t.limits.min as u64).checked_mul(16).ok_or("table too large")?;writeln!(out,"  %table{i} = call ptr @calloc(i64 {}, i64 1)
  %table_oom{i} = icmp eq ptr %table{i}, null
  br i1 %table_oom{i}, label %table_failure{i}, label %table_ok{i}
table_failure{i}:
  call void @w2l_trap(i32 5)
  unreachable
table_ok{i}:
  store ptr %table{i}, ptr @w2l_table_{i}
  store i64 {}, ptr @w2l_table_size_{i}",bytes.max(1),t.limits.min).unwrap();}
    for (i,el) in m.elements.iter().enumerate() {
        match &el.mode {ElementMode::Active{table,offset:e}=>{let off=offset(e)?;let len=el.init.len();writeln!(out,"  %elem_dst{i} = call ptr @w2l_table_ptr_{table}(i32 {off}, i32 {len})
  call void @llvm.memcpy.p0.p0.i64(ptr %elem_dst{i}, ptr @w2l_elem_{i}, i64 {}, i1 false)
  store i1 true, ptr @w2l_elem_dropped_{i}",len*16).unwrap();},ElementMode::Declarative=>{writeln!(out,"  store i1 true, ptr @w2l_elem_dropped_{i}").unwrap()},ElementMode::Passive=>{}}
    }
    for (i,d) in m.data.iter().enumerate() {if let DataMode::Active{memory:idx,offset:e}=&d.mode {if *idx!=0{return Err("invalid data memory index".into())}writeln!(out,"  call void @w2l_data_init_{i}(i32 {}, i32 0, i32 {})
  store i1 true, ptr @w2l_data_dropped_{i}",offset(e)?,d.bytes.len()).unwrap();}}
    if let Some(start)=m.start {out.push_str("  %start_args = alloca [1 x i128], align 16
  %start_results = alloca [1 x i128], align 16
");writeln!(out,"  call void @w2l_f{start}(ptr %start_args, ptr %start_results)").unwrap();}
    out.push_str("  ret void
}
");
    for ex in &m.exports {let h=hex(&ex.name);match ex.desc {
        ExportDesc::Func(i)=>writeln!(out,"define void @w2l_export_{h}(ptr %args, ptr %results) {{
entry:
  store i32 0, ptr @w2l_depth
  call void @w2l_f{i}(ptr %args, ptr %results)
  ret void
}}").unwrap(),
        ExportDesc::Global(i)=>writeln!(out,"define void @w2l_global_{h}(ptr %out) {{
entry:
  %v = load i128, ptr @w2l_g{i}, align 16
  store i128 %v, ptr %out, align 1
  ret void
}}").unwrap(),
        ExportDesc::Memory(_)=>writeln!(out,"define ptr @w2l_memory_{h}(ptr %out) {{
entry:
  %size = load i64, ptr @w2l_mem_bytes
  store i64 %size, ptr %out, align 1
  %base = load ptr, ptr @w2l_mem_base
  ret ptr %base
}}").unwrap(),
        ExportDesc::Table(_)=>{},
    }}
    Ok(out)
}

fn emit_tables(m:&wasm::Module,out:&mut String)->Result<(),String> {
