404	/// Decode a core-version-1 binary using the WebAssembly 2.0 feature set.
405	pub fn parse(bytes: &[u8]) -> Result<Module> {
406	    let mut r = Reader::new(bytes);
407	    if r.read_bytes(4)? != b"\0asm" { return Err(Error::new(0, "bad WebAssembly magic")); }
408	    if r.read_bytes(4)? != [1, 0, 0, 0] { return Err(Error::new(4, "unsupported WebAssembly version")); }
409	    let mut module = Module::default();
410	    let mut func_types = Vec::new();
411	    let mut bodies: Vec<(Vec<LocalDecl>, Vec<u8>, usize)> = Vec::new();
412	    let mut previous_order = 0u8;
413	    while !r.is_empty() {
414	        let section_at = r.offset(); let id = r.read_u8()?;
415	        let size = r.read_u32()? as usize;
416	        let base = r.offset(); let contents = r.read_bytes(size)?;
417	        let mut s = Reader::with_offset(contents, base);
418	        if id != 0 {
419	            let order = match id { 1..=9 => id, 12 => 10, 10 => 11, 11 => 12, _ => return Err(Error::new(section_at, "unknown or unsupported section")) };
420	            if order <= previous_order { return Err(Error::new(section_at, "duplicate or out-of-order section")); }
421	            previous_order = order;
422	        }
423	        match id {
424	            0 => { let name = s.read_name()?; let data = s.read_bytes(s.remaining())?.to_vec(); module.customs.push(CustomSection { name, data }); }
425	            1 => { module.types = s.vector(|r| {
426	                let at = r.offset(); if r.read_u8()? != 0x60 { return Err(Error::new(at, "unsupported type definition")); }
427	                Ok(FuncType { params: r.vector(|r| r.read_val_type())?, results: r.vector(|r| r.read_val_type())? })
428	            })?; }
429	            2 => { module.imports = s.vector(|r| {
430	                let module = r.read_name()?; let name = r.read_name()?; let at = r.offset();
431	                let desc = match r.read_u8()? {
432	                    0 => ImportDesc::Func(r.read_u32()?), 1 => ImportDesc::Table(table_type(r)?),
433	                    2 => ImportDesc::Memory(memory_type(r)?), 3 => ImportDesc::Global(global_type(r)?),
434	                    _ => return Err(Error::new(at, "invalid or unsupported import kind")),
435	                }; Ok(Import { module, name, desc })
436	            })?; }
437	            3 => { func_types = s.vector(|r| r.read_u32())?; }
438	            4 => { module.tables = s.vector(table_type)?; }
439	            5 => { module.memories = s.vector(memory_type)?; }
440	            6 => { module.globals = s.vector(|r| Ok(Global { ty: global_type(r)?, init: const_expr(r)? }))?; }
441	            7 => { module.exports = s.vector(|r| {
442	                let name = r.read_name()?; let at = r.offset(); let kind = r.read_u8()?; let index = r.read_u32()?;
443	                let desc = match kind { 0 => ExportDesc::Func(index), 1 => ExportDesc::Table(index), 2 => ExportDesc::Memory(index), 3 => ExportDesc::Global(index), _ => return Err(Error::new(at, "invalid or unsupported export kind")) };
444	                Ok(Export { name, desc })
445	            })?; }
446	            8 => { module.start = Some(s.read_u32()?); }
447	            9 => { module.elements = s.vector(element)?; }
448	            10 => { bodies = s.vector(|r| {
449	                let size = r.read_u32()? as usize; let base = r.offset(); let bytes = r.read_bytes(size)?;
450	                let mut body = Reader::with_offset(bytes, base);
451	                let mut total = 0u32;
452	                let locals = body.vector(|r| {
453	                    let at = r.offset(); let count = r.read_u32()?; let ty = r.read_val_type()?;
454	                    total = total.checked_add(count).ok_or_else(|| Error::new(at, "too many locals"))?;
455	                    Ok(LocalDecl { count, ty })
456	                })?;
457	                let body_offset = body.offset(); let instructions = body.read_bytes(body.remaining())?.to_vec();
458	                Ok((locals, instructions, body_offset))
459	            })?; }
460	            11 => { module.data = s.vector(data)?; }
461	            12 => { module.data_count = Some(s.read_u32()?); }
462	            _ => unreachable!(),
463	        }
464	        if !s.is_empty() { return Err(Error::new(s.offset(), "section has trailing bytes")); }
465	    }
466	    if func_types.len() != bodies.len() { return Err(Error::new(bytes.len(), "function and code section lengths differ")); }
467	    module.functions = func_types.into_iter().zip(bodies).map(|(type_index, (locals, body, body_offset))| Function { type_index, locals, body, body_offset }).collect();
