473	/// Module-level index spaces, constructed once to keep validation linear even
474	/// when a module contains many imports and instructions.
475	struct Context<'a> {
476	    types: &'a [FuncType],
477	    funcs: Vec<&'a FuncType>,
478	    tables: Vec<TableType>,
479	    memories: Vec<MemoryType>,
480	    globals: Vec<GlobalType>,
481	    imported_globals: usize,
482	    elements: &'a [Element],
483	    data_count: Option<u32>,
484	}
485	
486	fn check_const(ctx: &Context<'_>, expr: &ConstExpr, expected: ValType) -> Result<()> {
487	    let ty = match expr.op {
488	        ConstOp::I32(_) => ValType::I32, ConstOp::I64(_) => ValType::I64,
489	        ConstOp::F32(_) => ValType::F32, ConstOp::F64(_) => ValType::F64,
490	        ConstOp::V128(_) => ValType::V128, ConstOp::RefNull(t) => t,
491	        ConstOp::RefFunc(idx) => {
492	            if idx as usize >= ctx.funcs.len() { return Err(Error::new(0, "constant expression function index out of bounds")); }
493	            ValType::FuncRef
494	        }
495	        ConstOp::GlobalGet(idx) => {
496	            if idx as usize >= ctx.imported_globals { return Err(Error::new(0, "constant global.get must reference an imported global")); }
497	            let global = ctx.globals[idx as usize];
498	            if global.mutable { return Err(Error::new(0, "constant global.get references a mutable global")); }
499	            global.ty
500	        }
501	    };
502	    if ty != expected { return Err(Error::new(0, "constant expression type mismatch")); }
503	    Ok(())
504	}
505	
506	fn check_module(module: &Module) -> Result<()> {
507	    let mut ctx = Context {
508	        types: &module.types, funcs: Vec::new(), tables: Vec::new(), memories: Vec::new(),
509	        globals: Vec::new(), imported_globals: 0, elements: &module.elements, data_count: module.data_count,
510	    };
511	    for import in &module.imports {
512	        match import.desc {
513	            ImportDesc::Func(idx) => ctx.funcs.push(module.types.get(idx as usize).ok_or_else(|| Error::new(0, "import function type index out of bounds"))?),
514	            ImportDesc::Table(t) => ctx.tables.push(t),
515	            ImportDesc::Memory(t) => ctx.memories.push(t),
516	            ImportDesc::Global(t) => ctx.globals.push(t),
517	        }
518	    }
519	    ctx.imported_globals = ctx.globals.len();
520	    ctx.tables.extend(module.tables.iter().copied());
521	    ctx.memories.extend(module.memories.iter().copied());
522	    ctx.globals.extend(module.globals.iter().map(|g| g.ty));
523	    for func in &module.functions {
524	        ctx.funcs.push(module.types.get(func.type_index as usize).ok_or_else(|| Error::new(func.body_offset, "function type index out of bounds"))?);
525	    }
526	    if ctx.memories.len() > 1 { return Err(Error::new(0, "multiple memories are outside WebAssembly 2.0 scope")); }
527	    for global in &module.globals { check_const(&ctx, &global.init, global.ty.ty)?; }
528	    let mut names = HashSet::new();
529	    for export in &module.exports {
530	        if !names.insert(&export.name) { return Err(Error::new(0, "duplicate export name")); }
531	        let valid = match export.desc {
532	            ExportDesc::Func(i) => (i as usize) < ctx.funcs.len(),
533	            ExportDesc::Table(i) => (i as usize) < ctx.tables.len(),
534	            ExportDesc::Memory(i) => (i as usize) < ctx.memories.len(),
535	            ExportDesc::Global(i) => (i as usize) < ctx.globals.len(),
536	        };
537	        if !valid { return Err(Error::new(0, "export index out of bounds")); }
538	    }
539	    if let Some(start) = module.start {
540	        let ty = ctx.funcs.get(start as usize).ok_or_else(|| Error::new(0, "start function index out of bounds"))?;
541	        if !ty.params.is_empty() || !ty.results.is_empty() { return Err(Error::new(0, "start function must have type [] -> []")); }
542	    }
543	    for element in &module.elements {
544	        if let ElementMode::Active { table, offset } = &element.mode {
545	            let t = ctx.tables.get(*table as usize).ok_or_else(|| Error::new(0, "element table index out of bounds"))?;
546	            if t.element != element.ty { return Err(Error::new(0, "element segment/table type mismatch")); }
547	            check_const(&ctx, offset, ValType::I32)?;
548	        }
549	        for item in &element.init {
550	            match item {
551	                ElementInit::Func(i) => {
552	                    if *i as usize >= ctx.funcs.len() { return Err(Error::new(0, "element function index out of bounds")); }
553	                }
554	                ElementInit::Expr(e) => check_const(&ctx, e, element.ty)?,
555	            }
556	        }
557	    }
558	    for data in &module.data {
559	        if let DataMode::Active { memory, offset } = &data.mode {
560	            if *memory as usize >= ctx.memories.len() { return Err(Error::new(0, "data memory index out of bounds")); }
561	            check_const(&ctx, offset, ValType::I32)?;
562	        }
563	    }
564	    for func in &module.functions { check_body(&ctx, func)?; }
565	    Ok(())
566	}
