568	// The maximum valid log2 alignment, by memory opcode.
569	fn scalar_align(op: u8) -> u32 {
570	    match op {
571	        0x28 | 0x2a | 0x34 | 0x35 | 0x36 | 0x38 | 0x3e => 2,
572	        0x29 | 0x2b | 0x37 | 0x39 => 3,
573	        0x2e | 0x2f | 0x32 | 0x33 | 0x3b | 0x3d => 1,
574	        _ => 0,
575	    }
576	}
577	fn simd_align(op: u32) -> u32 {
578	    match op {
579	        0 | 11 => 4, 1..=6 | 10 | 87 | 91 | 93 => 3,
580	        9 | 86 | 90 | 92 => 2, 8 | 85 | 89 => 1, _ => 0,
581	    }
582	}
