584	fn check_body(ctx: &Context<'_>, func: &Function) -> Result<()> {
585	    let ty = &ctx.types[func.type_index as usize];
586	    let local_count = (ty.params.len() as u64) + func.local_count() as u64;
587	    if local_count > u32::MAX as u64 { return Err(Error::new(func.body_offset, "too many parameters and locals")); }
588	    let mut r = func.reader();
589	    // 0=root/block/loop, 1=if without else, 2=if with else.
590	    let mut control = vec![0u8];
591	    loop {
592	        let at = r.offset();
593	        let instruction = r.read_instruction()?;
594	        let op = instruction.opcode;
595	        use Immediate::*;
596	        match (&instruction.immediate, op) {
597	            (Block(BlockType::TypeIndex(i)), 0x02..=0x04) if *i as usize >= ctx.types.len() => return Err(Error::new(at, "block type index out of bounds")),
598	            (_, 0x02 | 0x03) => control.push(0),
599	            (_, 0x04) => control.push(1),
600	            (_, 0x05) => {
601	                if control.last() != Some(&1) { return Err(Error::new(at, "unexpected else")); }
602	                *control.last_mut().unwrap() = 2;
603	            }
604	            (_, 0x0b) => {
605	                control.pop();
606	                if control.is_empty() {
607	                    if !r.is_empty() { return Err(Error::new(r.offset(), "bytes after function end")); }
608	                    break;
609	                }
610	            }
611	            (Index(i), 0x0c | 0x0d) if *i as usize >= control.len() => return Err(Error::new(at, "branch label out of bounds")),
612	            (BrTable { targets, default }, 0x0e) if *default as usize >= control.len() || targets.iter().any(|i| *i as usize >= control.len()) => return Err(Error::new(at, "branch table label out of bounds")),
613	            (Index(i), 0x10 | 0xd2) if *i as usize >= ctx.funcs.len() => return Err(Error::new(at, "function index out of bounds")),
614	            (IndexPair(t, table), 0x11) => {
615	                if *t as usize >= ctx.types.len() { return Err(Error::new(at, "call_indirect type index out of bounds")); }
616	                let table = ctx.tables.get(*table as usize).ok_or_else(|| Error::new(at, "call_indirect table index out of bounds"))?;
617	                if table.element != ValType::FuncRef { return Err(Error::new(at, "call_indirect requires funcref table")); }
618	            }
619	            (Types(types), 0x1c) if types.len() != 1 => return Err(Error::new(at, "typed select requires exactly one type")),
620	            (Index(i), 0x20..=0x22) if *i as u64 >= local_count => return Err(Error::new(at, "local index out of bounds")),
621	            (Index(i), 0x23 | 0x24) => {
622	                let global = ctx.globals.get(*i as usize).ok_or_else(|| Error::new(at, "global index out of bounds"))?;
623	                if op == 0x24 && !global.mutable { return Err(Error::new(at, "global.set on immutable global")); }
624	            }
625	            (Index(i), 0x25 | 0x26) if *i as usize >= ctx.tables.len() => return Err(Error::new(at, "table index out of bounds")),
626	            (MemArg(m), 0x28..=0x3e) => {
627	                if ctx.memories.is_empty() { return Err(Error::new(at, "memory instruction without memory")); }
628	                if m.align > scalar_align(op) { return Err(Error::new(at, "memory alignment too large")); }
629	            }
630	            (_, 0x3f | 0x40) if ctx.memories.is_empty() => return Err(Error::new(at, "memory instruction without memory")),
631	            (_, 0xfc) => {
632	                match (instruction.subopcode.unwrap(), &instruction.immediate) {
633	                    (8, IndexPair(i, _)) | (9, Index(i)) => {
634	                        let n = ctx.data_count.ok_or_else(|| Error::new(at, "data index requires a data count section"))?;
635	                        if *i >= n { return Err(Error::new(at, "data index out of bounds")); }
636	                        if instruction.subopcode == Some(8) && ctx.memories.is_empty() { return Err(Error::new(at, "memory.init without memory")); }
637	                    }
638	                    (10 | 11, _) if ctx.memories.is_empty() => return Err(Error::new(at, "bulk memory instruction without memory")),
639	                    (12, IndexPair(elem, table)) => {
640	                        let e = ctx.elements.get(*elem as usize).ok_or_else(|| Error::new(at, "element index out of bounds"))?;
641	                        let t = ctx.tables.get(*table as usize).ok_or_else(|| Error::new(at, "table index out of bounds"))?;
642	                        if e.ty != t.element { return Err(Error::new(at, "table.init type mismatch")); }
643	                    }
644	                    (13, Index(i)) if *i as usize >= ctx.elements.len() => return Err(Error::new(at, "element index out of bounds")),
645	                    (14, IndexPair(dst, src)) => {
646	                        let dst = ctx.tables.get(*dst as usize).ok_or_else(|| Error::new(at, "table index out of bounds"))?;
647	                        let src = ctx.tables.get(*src as usize).ok_or_else(|| Error::new(at, "table index out of bounds"))?;
