    funcs=[]; tests=[]
    def add(op,args,ret,inputs):
        name=op.replace('.','_'); params=' '.join('(param '+t+')' for t in args)
        body=' '.join('local.get '+str(i) for i in range(len(args)))
        funcs.append(f'(func (export "{name}") {params} (result {ret}) {body} {op})')
