                so=d/(name+opt+'.so');command('clang',opt,'-shared','-fPIC','-Wl,-Bsymbolic',str(ll),'-lm','-o',str(so))
                run_pair(driver,so,wasm,check)
                print(name,opt,'passed',flush=True)

if __name__=='__main__': main()

