pub fn parse(bytes: &[u8]) -> Result<Self> { parse(bytes) }
pub fn imported_function_count(&self) -> usize { self.imports.iter().filter(|i| matches!(i.desc, ImportDesc::Func(_))).count() }
pub fn imported_table_count(&self) -> usize { self.imports.iter().filter(|i| matches!(i.desc, ImportDesc::Table(_))).count() }
pub fn imported_memory_count(&self) -> usize { self.imports.iter().filter(|i| matches!(i.desc, ImportDesc::Memory(_))).count() }
pub fn imported_global_count(&self) -> usize { self.imports.iter().filter(|i| matches!(i.desc, ImportDesc::Global(_))).count() }
pub fn function_type_index(&self, index: u32) -> Option<u32> {
    let mut imports = self.imports.iter().filter_map(|i| match i.desc { ImportDesc::Func(t) => Some(t), _ => None });
    let imported = self.imported_function_count();
    if (index as usize) < imported { imports.nth(index as usize) }
    else { self.functions.get(index as usize - imported).map(|f| f.type_index) }
}
pub fn function_type(&self, index: u32) -> Option<&FuncType> {
    self.types.get(self.function_type_index(index)? as usize)
}
pub fn table_type(&self, index: u32) -> Option<TableType> {
    let imported = self.imported_table_count();
    if (index as usize) < imported {
        self.imports.iter().filter_map(|i| match i.desc { ImportDesc::Table(t) => Some(t), _ => None }).nth(index as usize)
    } else { self.tables.get(index as usize - imported).copied() }
